<script lang="ts">
 import NoteTypes from './NoteTypes.svelte';
 import {NOTE_TYPES_KEY} from '../core/note-types';
 import SoundPreview from './SoundPreview.svelte';
 import PluginSetting from './PluginSetting.svelte';
 import {diagnostics} from './diagnostics';
 import type {UpdateStatus} from './app-updates';
 import {SCHEMA_VERSION} from '../storage/schema';
 import PluginIcon from './PluginIcon.svelte';
 import {mapTools} from '../plugins/map-tools';
 import {surface} from './surfaces';
 import type {Core} from '../core/core';
 import type {PluginRuntime} from '../plugins/runtime';
 import {templates} from '../plugins/builtins';
 import {dynamicsPlugins} from '../plugins/dynamics';
 import {daily} from '../plugins/daily';
 import {communityPlugin} from '../plugins/sandbox';
 import {validateManifest,validSettingValue,type Manifest,type Plugin} from '../plugins/api';
 import {download,exportBackup,parseBackup,importBackup} from '../core/backup';
 import type {Snapshot} from '../core/model';
 import {onMount} from 'svelte';

 import Themes from './Themes.svelte';
 import Vaults from './Vaults.svelte';
 import NativeBackup from './NativeBackup.svelte';
 import type {Preferences} from '../core/preferences';
 import {readPackage,type PluginPackage} from '../plugins/package';
 let {extraBuiltins=[],core,runtime,persistent,prefs,onclose,onpersist,onnotify,updateStatus,oncheckupdate,onupdate}:{extraBuiltins?:Plugin[];core:Core;runtime:PluginRuntime;persistent:boolean;prefs:Preferences;onclose:()=>void;onpersist:()=>Promise<void>;onnotify:(s:string)=>void;updateStatus:UpdateStatus;oncheckupdate:()=>Promise<void>;onupdate:()=>Promise<void>}=$props();
 let rendererMode=$state('');let diagnosticMessage=$state('');
 async function copyDiagnostics(){const text=JSON.stringify(diagnostics({atoms:core.data.atoms.length,links:core.data.links.length}),null,2);try{await navigator.clipboard.writeText(text);diagnosticMessage='\u0414\u0438\u0430\u0433\u043d\u043e\u0441\u0442\u0438\u043a\u0430 \u0441\u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u043d\u0430';}catch{download('posphorea-diagnostics.json',text,'application/json');diagnosticMessage='\u0424\u0430\u0439\u043b \u0434\u0438\u0430\u0433\u043d\u043e\u0441\u0442\u0438\u043a\u0438 \u043f\u0435\u0440\u0435\u0434\u0430\u043d \u0431\u0440\u0430\u0443\u0437\u0435\u0440\u0443.';}}
 let page=$state<'general'|'plugins'|'data'>('general');let pluginOrigin=$state<'general'|'plugins'>('plugins');let selectedPlugin=$state<Manifest|null>(null);let values=$state<Record<string,boolean|string|number>>({});
 async function openPlugin(manifest:Manifest){const next:Record<string,boolean|string|number>={};for(const field of manifest.settings||[]){const stored=await core.storage.getSetting<boolean|string|number>(`plugin:${manifest.id}:${field.key}`);next[field.key]=validSettingValue(field,stored)?stored!:field.default;}values=next;selectedPlugin=manifest;}
  // The real version, stamped again on every build. A phone keeps serving the
  // previously installed bundle until the page is reloaded, so this line is how
  // you can tell an updated app from a stale one without guessing.
  const appVersion=import.meta.env.VITE_APP_VERSION||'0.0.0';
  const buildId=import.meta.env.VITE_BUILD_ID||'сборка неизвестна';
 let packageData=$state<PluginPackage|null>(null);let developerMode=$state(false);
 let revision=$state(0);let error=$state('');let busy=$state(false);let installed=$state<{manifest:Manifest;source:string;style?:string;assets?:Record<string,number[]>;enabled:boolean}[]>([]);let pendingManifest=$state<Manifest|null>(null);let pendingSource=$state('');let importData=$state<import('../core/backup').MapBackupData|null>(null);let backups=$state<{at:string;data:Snapshot}[]>([]);let usage=$state('');let root:HTMLDivElement;
 onMount(()=>{root.focus();const map=document.querySelector('canvas.map'),updateRenderer=()=>rendererMode=map?.getAttribute('data-renderer')||'';updateRenderer();const observer=new MutationObserver(updateRenderer);if(map)observer.observe(map,{attributes:true,attributeFilter:['data-renderer']});Promise.all([core.storage.getSetting<typeof installed>('community-plugins'),core.storage.getSetting<typeof backups>('backups'),navigator.storage.estimate()]).then(([plugins,copies,estimate])=>{installed=plugins||[];backups=copies||[];usage=`${((estimate.usage||0)/1024/1024).toFixed(1)} МБ занято`;}).catch(e=>error=e.message);return()=>observer.disconnect();});
 async function run(fn:()=>Promise<unknown>){busy=true;error='';try{await fn();revision++;}catch(e){error=(e as Error).message;}finally{busy=false;}}
 async function checkpoint(){const copies=await core.storage.getSetting<typeof backups>('backups')||[];backups=[{at:new Date().toISOString(),data:core.data},...copies].slice(0,3);await core.storage.transaction([{kind:'setting',key:'backups',value:$state.snapshot(backups)}]);}
 async function toggleBuiltin(id:string){if(runtime.active.has(id))runtime.disable(id);else await runtime.enable([templates,daily,...dynamicsPlugins,...mapTools,...extraBuiltins].find(p=>p.manifest.id===id)!);await core.storage.transaction([{kind:'setting',key:'disabled-builtins',value:[templates,daily,...dynamicsPlugins,...mapTools,...extraBuiltins].filter(p=>!runtime.active.has(p.manifest.id)).map(p=>p.manifest.id)}]);}
 async function persistPlugins(){await core.storage.transaction([{kind:'setting',key:'community-plugins',value:$state.snapshot(installed)}]);}
 async function fileText(e:Event){const input=e.target as HTMLInputElement;const file=input.files?.[0];input.value='';if(!file)throw Error('Файл не выбран.');if(file.size>50_000_000)throw Error('Файл слишком большой.');return file.text();}
 function keys(e:KeyboardEvent){if(e.key==='Escape'&&!busy)onclose();if(e.key==='Tab'){const els=[...root.querySelectorAll<HTMLElement>('button:not([disabled]),input,select,summary')].filter(el=>el.getClientRects().length);if(e.shiftKey&&(document.activeElement===els[0]||document.activeElement===root)){e.preventDefault();els.at(-1)?.focus();}else if(!e.shiftKey&&document.activeElement===els.at(-1)){e.preventDefault();els[0]?.focus();}}}
</script>
<div class="scrim" use:surface={{close:onclose,blocked:()=>busy}}><div class="editor settings" bind:this={root} tabindex="-1" role="dialog" aria-modal="true" aria-label="Настройки" onkeydown={keys}>
 <div class="row"><h2>{page==='data'?'Данные и копии':page==='plugins'?(selectedPlugin?.name||'Плагины'):'Настройки'}</h2><button aria-label="Закрыть настройки" disabled={busy} onclick={onclose}><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="m6 6 12 12M18 6 6 18"/></svg></button></div>
 {#if error}<p role="alert" class="inline-error">{error}</p>{/if}
 {#if page==='general'}<div class="settings-links"><button onclick={()=>{pluginOrigin='general';page='plugins';void run(()=>openPlugin(extraBuiltins.find(p=>p.manifest.id==='builtin.appearance')!.manifest));}}><PluginIcon id="builtin.appearance"/><span>Оформление<small>Темы и атмосфера карты</small></span><svg viewBox="0 0 24 24"><path d="m9 5 7 7-7 7"/></svg></button><button aria-label="Плагины →" onclick={()=>{pluginOrigin='plugins';page='plugins';}}><PluginIcon id="builtin.physics"/><span>Плагины<small>Жесты, зум, звук и поведение</small></span><svg viewBox="0 0 24 24"><path d="m9 5 7 7-7 7"/></svg></button><button onclick={()=>page='data'}><PluginIcon id="builtin.folders"/><span>Данные и копии<small>Всё хранится на этом устройстве</small></span><svg viewBox="0 0 24 24"><path d="m9 5 7 7-7 7"/></svg></button></div>{/if}{#if page==='data'}<button class="settings-back" onclick={()=>page='general'}>← Настройки</button>

 <section><small>НА ЭТОМ УСТРОЙСТВЕ</small><h3>{persistent?'Хранилище закреплено':'Локальное хранилище'}</h3><p>{usage}. Карта остаётся на устройстве. Без аккаунта и отправки заметок на сервер.</p>{#if !persistent}<p>Браузер пока не предоставил защиту от автоматической очистки при нехватке места.</p><button disabled={busy} onclick={()=>run(onpersist)}>Запросить защиту хранилища</button>{/if}</section>
 <NativeBackup {core} bind:busy/><details class="vault-details"><summary>Markdown и Obsidian</summary><Vaults {core}/></details><details class="legacy-backup"><summary>Дополнительные форматы и снимки</summary><section><p>JSON переносит атомы и связи. Для всех данных используйте полную копию выше.</p><div class="button-wrap"><button disabled={busy} onclick={()=>run(async()=>download('posphorea-map.json',exportBackup(core.data,await core.storage.getSetting(NOTE_TYPES_KEY))))}>Экспорт карты</button><button disabled={busy} onclick={()=>run(async()=>download('posphorea.sqlite3',await core.storage.exportDatabase(),'application/vnd.sqlite3'))}>Скачать SQLite</button><label class="file-button">Импорт карты<input type="file" accept=".json,application/json" disabled={busy} onchange={e=>run(async()=>{importData=parseBackup(await fileText(e));})}/></label></div>
 {#if importData}<div class="confirm"><p>В копии {importData.atoms.length} атомов и {importData.links.length} связей. Импорт добавит отсутствующие записи. Существующие атомы сохранят свои текущие версии.</p><button disabled={busy} onclick={()=>run(async()=>{await checkpoint();const n=await importBackup(core,$state.snapshot(importData!));importData=null;onnotify(`Добавлено атомов: ${n}`);})}>Добавить в карту</button><button onclick={()=>importData=null}>Отмена</button></div>{/if}
 <details><summary>Локальные снимки · {backups.length}</summary><p>До трёх последних снимков перед удалением или импортом. Они не защищают от потери устройства.</p><button disabled={busy} onclick={()=>run(checkpoint)}>Создать снимок</button>{#each backups as copy}<button disabled={busy} onclick={()=>run(async()=>{importData=parseBackup(exportBackup(copy.data));})}>Восстановить отсутствующее · {new Date(copy.at).toLocaleString('ru-RU')}</button>{/each}</details></section></details>
 {/if}
 {#if page==='plugins'}<button class="settings-back" onclick={()=>{if(selectedPlugin){selectedPlugin=null;page=pluginOrigin;}else page='general';}}>← {selectedPlugin&&pluginOrigin==='plugins'?'Все плагины':'Настройки'}</button>
 {#if selectedPlugin}<section>{#if selectedPlugin.id!=='builtin.templates'}<p class="plugin-description">{selectedPlugin.description}</p>{/if}{#if selectedPlugin.id==='builtin.templates'}<NoteTypes {core}/>{/if}{#if selectedPlugin.id==='builtin.appearance'}<Themes {core} {prefs}/>{/if}{#each selectedPlugin.settings||[] as field}<PluginSetting {field} value={values[field.key]??field.default} disabled={busy} onchange={value=>run(async()=>{const id=selectedPlugin!.id;await core.storage.transaction([{kind:'setting',key:`plugin:${id}:${field.key}`,value}]);values[field.key]=value;core.emit('preferences:plugin-setting',{plugin:id,key:field.key});})}/>{/each}{#if selectedPlugin.id==='builtin.sound'}<SoundPreview/>{/if}</section>{:else}
 <section class="plugin-list">{#key revision}{#each [templates,daily,...dynamicsPlugins,...mapTools,...extraBuiltins] as plugin}<div class="plugin-row"><PluginIcon id={plugin.manifest.id}/><div><strong>{plugin.manifest.name}</strong>{#if (plugin.manifest.settings?.length||['builtin.appearance','builtin.templates'].includes(plugin.manifest.id))}<button disabled={busy} onclick={()=>run(()=>openPlugin(plugin.manifest))}><span class="sr-only">Настройки</span><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="m9 5 7 7-7 7"/></svg></button>{/if}<small>{plugin.manifest.description}</small></div><button class="plugin-switch" disabled={busy} aria-pressed={runtime.active.has(plugin.manifest.id)} onclick={()=>run(()=>toggleBuiltin(plugin.manifest.id))}><span class="sr-only">{runtime.active.has(plugin.manifest.id)?'Выключить':'Включить'}</span><i aria-hidden="true"></i></button></div>{/each}{/key}
 {#each installed as plugin,i}<div class="plugin-row"><PluginIcon id={plugin.manifest.id}/><div><strong>{plugin.manifest.name}</strong>{#if (plugin.manifest.settings?.length||['builtin.appearance','builtin.templates'].includes(plugin.manifest.id))}<button disabled={busy} onclick={()=>run(()=>openPlugin(plugin.manifest))}><span class="sr-only">Настройки</span><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="m9 5 7 7-7 7"/></svg></button>{/if}<small>{plugin.manifest.permissions.join(', ')}</small></div><button disabled={busy} onclick={()=>run(async()=>{if(plugin.enabled)runtime.disable(plugin.manifest.id);else await runtime.enable(communityPlugin(plugin.manifest,plugin.source,plugin));installed[i].enabled=!plugin.enabled;await persistPlugins();})}>{plugin.enabled?'Выключить':'Включить'}</button><button disabled={busy} aria-label={`Удалить плагин ${plugin.manifest.name}`} onclick={()=>run(async()=>{runtime.disable(plugin.manifest.id);installed=installed.filter((_,j)=>j!==i);await persistPlugins();})}>×</button></div>{/each}
 <details><summary>Установить плагин</summary><p>Выберите один файл .posphorea. Перед установкой мы покажем разрешения.</p><label class="file-button">Выбрать .posphorea<input type="file" accept=".posphorea,.phosphora,.phosphored" aria-label="Пакет плагина" disabled={busy} onchange={e=>run(async()=>{const input=e.currentTarget;const file=input.files?.[0];input.value='';if(!file)return;if(!/[.](posphorea|phosphora|phosphored)$/i.test(file.name))throw Error('Expected .posphorea');packageData=readPackage(new Uint8Array(await file.arrayBuffer()));pendingManifest=packageData.manifest;pendingSource=packageData.source;})}/></label><label>Режим разработчика<input type="checkbox" bind:checked={developerMode}/></label>{#if developerMode}<label class="file-button">Manifest.json<input type="file" accept=".json" onchange={e=>run(async()=>{const m=JSON.parse(await fileText(e));validateManifest(m);if(m.id.startsWith('builtin.'))throw Error('Reserved plugin ID');pendingManifest=m;})}/></label><label class="file-button">Main.js<input type="file" accept=".js,.mjs" onchange={e=>run(async()=>pendingSource=await fileText(e))}/></label>{/if}
 {#if pendingManifest&&pendingSource}<div class="confirm"><h3>{pendingManifest.name}</h3><p>Разрешения: {pendingManifest.permissions.join(', ')||'нет'}. {pendingManifest.permissions.includes('atoms.write')?'Плагин сможет создавать, менять и удалять атомы.':''}</p><button disabled={busy} onclick={()=>run(async()=>{if(installed.some(p=>p.manifest.id===pendingManifest!.id))throw Error('Сначала удалите установленную версию этого плагина.');await runtime.enable(communityPlugin($state.snapshot(pendingManifest!),pendingSource,$state.snapshot(packageData)||undefined));installed=[...installed,{manifest:$state.snapshot(pendingManifest!),source:pendingSource,style:packageData?.style,assets:packageData?.assets,enabled:true}];await persistPlugins();pendingManifest=null;pendingSource='';packageData=null;onnotify('Плагин установлен. Команды доступны в меню карты.');})}>Разрешить и установить</button></div>{/if}</details></section>
 {/if}{/if}
 {#if page==='general'}<section class="settings-about"><p class="app-version">Phosphora {appVersion}</p>{#if updateStatus.available}<button class="check-update" onclick={onupdate}>Обновить приложение</button>{:else}<button class="check-update" disabled={updateStatus.checking} onclick={()=>oncheckupdate()}>{updateStatus.checking?'Проверяем…':'Проверить обновление'}</button>{/if}<p role="status">{updateStatus.message}</p><details class="render-diagnostics"><summary>О приложении и диагностика</summary><p>Сборка {buildId} · схема {SCHEMA_VERSION}</p><p>Отрисовка: <strong>{rendererMode==='webgl'?'WebGL':rendererMode==='canvas'?'Canvas 2D':'Определяется'}</strong></p><button onclick={copyDiagnostics}>Скопировать диагностику</button>{#if diagnosticMessage}<p role="status">{diagnosticMessage}</p>{/if}</details></section>
 {/if}</div></div>
